#ifdef X6_RESET_COIN_STATE
	/* X6: one module session runs many games and has no config file, so the
	 * reset below never happens; a coin lockout written by one game would lock
	 * coins out of the next (pacman after the expanded set). Clear per load. */
	{
		int x6_i;
		for (x6_i = 0; x6_i < COIN_COUNTERS; x6_i++)
			coins[x6_i] = lastcoin[x6_i] = coinlockedout[x6_i] = 0;
	}
#endif

/* X6: reuse the existing name storage across game reloads. */
snprintf(joynames[tot], sizeof(joynames[tot]), "JS %d", i * 10 + j);
joylist[tot].name = joynames[tot];

/* X6: these per-load path buffers are owned here. Clear them so a
 * subsequent game load does not lose the old allocation. */
free(nvdir);         nvdir = NULL;
free(hidir);         hidir = NULL;
free(cfgdir);        cfgdir = NULL;
free(screenshotdir); screenshotdir = NULL;
free(memcarddir);    memcarddir = NULL;
free(stadir);        stadir = NULL;
free(artworkdir);    artworkdir = NULL;
free(cheatdir);      cheatdir = NULL;

int av_enable = RETRO_AV_ENABLE_VIDEO | RETRO_AV_ENABLE_AUDIO;
if (!environ_cb(RETRO_ENVIRONMENT_GET_AUDIO_VIDEO_ENABLE, &av_enable))
   av_enable = RETRO_AV_ENABLE_VIDEO | RETRO_AV_ENABLE_AUDIO;
mame2000_video_enabled = (av_enable & RETRO_AV_ENABLE_VIDEO) != 0;

#ifdef X6_GAME_SAMPLE_PATH
      /* Preserve the normal system path; also support samples beside the ROMs.
       * ZIP sample sets avoid requiring a new Melis directory-stat endpoint. */
      snprintf(IMAMESAMPLEPATH, SAMPLE_PATH_BUF_SIZE, "%s/samples;%s/samples",
               core_sys_directory, IMAMEBASEPATH);
#else

#ifdef X6_GALAGA_C_Z80
   /* Device compatibility trial: all three Galaga CPUs use the C reference. */
   if (!strcmp(drivers[game_index]->name, "galaga"))
      use_drz80 = use_drz80_snd = 0;
#endif

#ifdef X6_ALTBEAST_DRZ80_SOUND
   /* Experimental sound-only substitution; leave other games' selections intact. */
   if (!strcmp(drivers[game_index]->name, "altbeast"))
      use_drz80_snd = 1;
#endif

#ifdef X6_EXPANDED_C_Z80
   /* X6: the substitutions below rewrite the shared MachineDriver in place, and
    * clones/siblings share one (pacman and mspacman). Within one module session
    * the menu loads several games, so restore the reference CPU types first and
    * make the selection independent of launch order. */
   {
      int x6_c;
      for (x6_c = 0; x6_c < MAX_CPU; x6_c++)
      {
         int *x6_type = (int*)&(drivers[game_index]->drv->cpu[x6_c].cpu_type);
#if (HAS_DRZ80)
         if (((*x6_type)&0xff) == CPU_DRZ80) *x6_type = ((*x6_type)&(~0xff))|CPU_Z80;
#endif
#if (HAS_CYCLONE)
         if (((*x6_type)&0xff) == CPU_CYCLONE) *x6_type = ((*x6_type)&(~0xff))|CPU_M68000;
#endif
      }
   }
   /* X6 expanded set: C Z80 where DrZ80 failed under ARM926 QEMU.
    * System 16 sound Z80: unload fault (altbeast, Codex; wb3, Claude).
    * pacman: silent audio on DrZ80 while native C runs produce sound. */
   {
      extern void sys16_vh_screenrefresh(struct osd_bitmap *bitmap,int full_refresh);
      if (drivers[game_index]->drv->vh_update == sys16_vh_screenrefresh
          || !strcmp(drivers[game_index]->name, "pacman"))
         use_drz80 = use_drz80_snd = 0;
   }
#endif

/* Number actually mixed, separate from the next mixer's requested length. */
int samples_ready = 0;
static unsigned audio_fraction;
static int next_sample_count(void)
{
#ifdef X6_CALL_RATE_AUDIO
    /* X6: the frontend calls the core at 60 Hz, or at the rounded refresh for
     * boards below 59 Hz. Produce exactly sample_rate per second of calls so
     * the launcher's audio reserve does not drain (55/57/60.606 Hz boards). */
    {
        double fps = Machine->drv->frames_per_second;
        unsigned call_hz = fps < 59.0 ? (unsigned)(fps + 0.5) : 60u;
        audio_fraction += Machine->sample_rate;
        int count = audio_fraction / call_hz;audio_fraction %= call_hz;
        return count;
    }
#endif
    if (Machine->drv->frames_per_second == 60.0) {
        audio_fraction += Machine->sample_rate;
        int count = audio_fraction / 60;audio_fraction %= 60;
        return count;
    }
    return Machine->sample_rate / Machine->drv->frames_per_second;
}

/* X6: release the stereo buffer before the next game allocates it. */
free(samples_buffer);
samples_buffer = NULL;
samples_per_frame = 0;samples_ready = 0;audio_fraction = 0;

#ifdef X6_FIVE_GAMES
	/* X6: reselect geometry and dirty mode for each newly loaded driver. */
	gfx_width = gfx_height = 0;
	use_dirty = -1;
	mame2000_direct_frame_data = 0;
	mame2000_direct_frame_pitch = 0;
#endif

#ifdef X6_GAME_SAMPLE_PATH
			/* Restore the init.wav sample fallback also used in MAME 0.78.
			 * This remains sample-based, not full Namco 54xx emulation. */
			else { sample_start(0,1,0); }
#endif

#ifdef X6_ALTBEAST_TARGET_RATE
		/* The X6 host consumes 22050 Hz. Avoid high-rate FM synthesis that
		 * the frontend would immediately downsample; keep chip clocks intact. */
		if (!strcmp(Machine->gamedrv->name,"altbeast")) fixed_rate = 0;
#endif
#ifdef X6_YM2151_TARGET_RATE
		/* Same treatment for the expanded set's other YM2151 boards. */
		{
			static const char *const x6_ym2151_games[] =
				{"goldnaxe","wb3","shinobi","rastan","contra","jackal","ddragon",0};
			int x6_i;
			for (x6_i = 0; x6_ym2151_games[x6_i]; x6_i++)
				if (!strcmp(Machine->gamedrv->name,x6_ym2151_games[x6_i])) fixed_rate = 0;
		}
#endif

#ifdef X6_FIVE_GAMES
	/* System 16 has refresh/freeze state in its video callback. Advance that
	 * prefix on omitted frames; its raster/tilemap work returns early. */
	else {
		extern int mame2000_video_enabled;
		extern void sys16_vh_screenrefresh(struct osd_bitmap *,int);
		if (!mame2000_video_enabled && Machine->drv->vh_update==sys16_vh_screenrefresh)
			sys16_vh_screenrefresh(Machine->scrbitmap,bitmap_dirty);
	}
#endif

#ifdef X6_NATIVE_PROFILE
	extern uint64_t x6_native_profile_now(void);
	extern void x6_native_profile_opm(uint64_t,unsigned);
	uint64_t x6_profile_started=x6_native_profile_now();
	unsigned x6_profile_samples=(unsigned)length;
#endif

